import { PrismaClient, Symbol, MarketData, Prisma } from '@prisma/client';

const prisma = new PrismaClient();

export interface SymbolWithMarketData extends Symbol {
  latestMarketData?: MarketData | null;
  score?: number;
}

export interface MarketDataFilters {
  symbolId?: string;
  symbolCode?: string;
  startDate?: Date;
  endDate?: Date;
  minPrice?: number;
  maxPrice?: number;
  sector?: string;
  market?: string;
}

export interface SymbolFilters {
  search?: string;
  sector?: string;
  market?: string;
  hasMarketData?: boolean;
  hasScores?: boolean;
  limit?: number;
  offset?: number;
}

export interface SymbolStatistics {
  totalSymbols: number;
  symbolsWithMarketData: number;
  symbolsWithScores: number;
  sectors: Array<{ name: string; count: number }>;
  markets: Array<{ name: string; count: number }>;
  latestUpdate: Date | null;
}

/**
 * سرویس مدیریت نمادها و داده‌های بازار
 * مسئولیت: مدیریت نمادهای بورسی و داده‌های بازار مرتبط
 */
export class SymbolService {
  
  /**
   * دریافت لیست نمادها با فیلتر
   */
  async getSymbols(filters: SymbolFilters = {}): Promise<SymbolWithMarketData[]> {
    try {
      const where: Prisma.SymbolWhereInput = {};
      
      if (filters.search) {
        where.OR = [
          { symbol: { contains: filters.search } },
          { name: { contains: filters.search } },
          { isin: { contains: filters.search } }
        ];
      }
      
      if (filters.sector) {
        where.sector = filters.sector;
      }
      
      if (filters.market) {
        where.market = filters.market;
      }
      
      const symbols = await prisma.symbol.findMany({
        where,
        include: {
          marketData: {
            orderBy: { date: 'desc' },
            take: 1
          },
          scores: {
            where: {
              mainDimensionId: { not: null },
              validTo: { gte: new Date() }
            },
            orderBy: { calculationDate: 'desc' },
            take: 1
          }
        },
        take: filters.limit || 100,
        skip: filters.offset || 0,
        orderBy: { symbol: 'asc' }
      });

      return symbols.map(symbol => ({
        ...symbol,
        latestMarketData: symbol.marketData[0] || null,
        score: symbol.scores[0] ? symbol.scores[0].value : undefined
      }));
    } catch (error) {
      console.error('خطا در دریافت لیست نمادها:', error);
      throw new Error('خطا در دریافت لیست نمادها');
    }
  }

  /**
   * دریافت اطلاعات کامل یک نماد
   */
  async getSymbolById(id: string): Promise<SymbolWithMarketData | null> {
    try {
      const symbol = await prisma.symbol.findUnique({
        where: { id },
        include: {
          marketData: {
            orderBy: { date: 'desc' },
            take: 10 // 10 رکورد آخر
          },
          scores: {
            where: {
              validTo: { gte: new Date() }
            },
            include: {
              mainDimension: true,
              subDimension: true,
              aspect: true,
              subCategory: true
            },
            orderBy: { calculationDate: 'desc' }
          }
        }
      });

      if (!symbol) {
        return null;
      }

      return {
        ...symbol,
        latestMarketData: symbol.marketData[0] || null,
        score: symbol.scores[0] ? symbol.scores[0].value : undefined
      };
    } catch (error) {
      console.error('خطا در دریافت اطلاعات نماد:', error);
      throw new Error('خطا در دریافت اطلاعات نماد');
    }
  }

  /**
   * دریافت اطلاعات نماد بر اساس کد
   */
  async getSymbolByCode(symbolCode: string): Promise<SymbolWithMarketData | null> {
    try {
      const symbol = await prisma.symbol.findUnique({
        where: { symbol: symbolCode },
        include: {
          marketData: {
            orderBy: { date: 'desc' },
            take: 1
          },
          scores: {
            where: {
              validTo: { gte: new Date() }
            },
            orderBy: { calculationDate: 'desc' },
            take: 1
          }
        }
      });

      if (!symbol) {
        return null;
      }

      return {
        ...symbol,
        latestMarketData: symbol.marketData[0] || null,
        score: symbol.scores[0] ? symbol.scores[0].value : undefined
      };
    } catch (error) {
      console.error('خطا در دریافت اطلاعات نماد:', error);
      throw new Error('خطا در دریافت اطلاعات نماد');
    }
  }

  /**
   * ایجاد نماد جدید
   */
  async createSymbol(data: {
    isin: string;
    symbol: string;
    name: string;
    market: string;
    sector: string;
    subSector?: string;
  }): Promise<Symbol> {
    try {
      // بررسی تکراری نبودن ISIN
      const existingIsin = await prisma.symbol.findUnique({
        where: { isin: data.isin }
      });

      if (existingIsin) {
        throw new Error(`ISIN ${data.isin} قبلاً ثبت شده است`);
      }

      // بررسی تکراری نبودن کد نماد
      const existingSymbol = await prisma.symbol.findUnique({
        where: { symbol: data.symbol }
      });

      if (existingSymbol) {
        throw new Error(`کد نماد ${data.symbol} قبلاً ثبت شده است`);
      }

      return await prisma.symbol.create({
        data: {
          isin: data.isin,
          symbol: data.symbol,
          name: data.name,
          market: data.market,
          sector: data.sector,
          subSector: data.subSector
        }
      });
    } catch (error) {
      console.error('خطا در ایجاد نماد:', error);
      throw error;
    }
  }

  /**
   * به‌روزرسانی اطلاعات نماد
   */
  async updateSymbol(id: string, data: Partial<{
    name: string;
    market: string;
    sector: string;
    subSector: string;
  }>): Promise<Symbol> {
    try {
      return await prisma.symbol.update({
        where: { id },
        data
      });
    } catch (error) {
      console.error('خطا در به‌روزرسانی نماد:', error);
      throw new Error('خطا در به‌روزرسانی نماد');
    }
  }

  /**
   * حذف نماد
   */
  async deleteSymbol(id: string): Promise<void> {
    try {
      // بررسی وجود داده‌های بازار قبل از حذف
      const marketDataCount = await prisma.marketData.count({
        where: { symbolId: id }
      });

      if (marketDataCount > 0) {
        throw new Error('امکان حذف نماد با داده‌های بازار موجود وجود ندارد');
      }

      // بررسی وجود امتیازها قبل از حذف
      const scoresCount = await prisma.score.count({
        where: { symbolId: id }
      });

      if (scoresCount > 0) {
        throw new Error('امکان حذف نماد با امتیازهای موجود وجود ندارد');
      }

      await prisma.symbol.delete({
        where: { id }
      });
    } catch (error) {
      console.error('خطا در حذف نماد:', error);
      throw error;
    }
  }

  /**
   * افزودن داده بازار جدید
   */
  async addMarketData(symbolId: string, data: {
    date: Date;
    price: number;
    change: number;
    changePercent: number;
    volume: number;
    tradeCount: number;
    // سایر فیلدها...
    [key: string]: unknown;
  }): Promise<MarketData> {
    try {
      // بررسی وجود نماد
      const symbol = await prisma.symbol.findUnique({
        where: { id: symbolId }
      });

      if (!symbol) {
        throw new Error('نماد مورد نظر یافت نشد');
      }

      // بررسی تکراری نبودن تاریخ برای این نماد
      const existingData = await prisma.marketData.findUnique({
        where: {
          symbolId_date: {
            symbolId,
            date: data.date
          }
        }
      });

      if (existingData) {
        throw new Error(`داده بازار برای تاریخ ${data.date.toISOString()} قبلاً ثبت شده است`);
      }

      return await prisma.marketData.create({
        data: {
          ...data,
          symbolId
        }
      });
    } catch (error) {
      console.error('خطا در افزودن داده بازار:', error);
      throw error;
    }
  }

  /**
   * دریافت داده‌های بازار با فیلتر
   */
  async getMarketData(filters: MarketDataFilters = {}): Promise<MarketData[]> {
    try {
      const where: Prisma.MarketDataWhereInput = {};

      if (filters.symbolId) {
        where.symbolId = filters.symbolId;
      }

      if (filters.startDate || filters.endDate) {
        where.date = {};
        if (filters.startDate) {
          where.date.gte = filters.startDate;
        }
        if (filters.endDate) {
          where.date.lte = filters.endDate;
        }
      }

      if (filters.minPrice || filters.maxPrice) {
        where.price = {};
        if (filters.minPrice) {
          where.price.gte = filters.minPrice;
        }
        if (filters.maxPrice) {
          where.price.lte = filters.maxPrice;
        }
      }

      // اگر symbolCode داده شده، ابتدا نماد را پیدا کن
      if (filters.symbolCode) {
        const symbol = await prisma.symbol.findUnique({
          where: { symbol: filters.symbolCode }
        });
        
        if (symbol) {
          where.symbolId = symbol.id;
        } else {
          return []; // نماد یافت نشد
        }
      }

      // اگر sector داده شده، نمادهای آن بخش را پیدا کن
      if (filters.sector) {
        const symbolsInSector = await prisma.symbol.findMany({
          where: { sector: filters.sector },
          select: { id: true }
        });
        
        where.symbolId = {
          in: symbolsInSector.map(s => s.id)
        };
      }

      // اگر market داده شده، نمادهای آن بازار را پیدا کن
      if (filters.market) {
        const symbolsInMarket = await prisma.symbol.findMany({
          where: { market: filters.market },
          select: { id: true }
        });
        
        where.symbolId = {
          in: symbolsInMarket.map(s => s.id)
        };
      }

      return await prisma.marketData.findMany({
        where,
        orderBy: { date: 'desc' },
        take: 100 // محدودیت برای جلوگیری از بار زیاد
      });
    } catch (error) {
      console.error('خطا در دریافت داده‌های بازار:', error);
      throw new Error('خطا در دریافت داده‌های بازار');
    }
  }

  /**
   * دریافت تعداد نمادها
   */
  async getSymbolCount(filters?: SymbolFilters): Promise<number> {
    try {
      const where: Prisma.SymbolWhereInput = {};
      
      if (filters?.search) {
        where.OR = [
          { symbol: { contains: filters.search } },
          { name: { contains: filters.search } },
          { isin: { contains: filters.search } }
        ];
      }
      
      if (filters?.sector) {
        where.sector = filters.sector;
      }
      
      if (filters?.market) {
        where.market = filters.market;
      }
      
      if (filters?.hasMarketData !== undefined) {
        where.marketData = filters.hasMarketData ? { some: {} } : { none: {} };
      }
      
      if (filters?.hasScores !== undefined) {
        where.scores = filters.hasScores ? { some: {} } : { none: {} };
      }

      return await prisma.symbol.count({ where });
    } catch (error) {
      console.error('خطا در دریافت تعداد نمادها:', error);
      throw new Error('خطا در دریافت تعداد نمادها');
    }
  }

  /**
   * دریافت آمار نمادها
   */
  async getSymbolStatistics(): Promise<SymbolStatistics> {
    try {
      const [
        totalSymbols,
        symbolsWithMarketData,
        symbolsWithScores,
        sectors,
        markets,
        latestMarketData
      ] = await Promise.all([
        prisma.symbol.count(),
        prisma.symbol.count({
          where: {
            marketData: { some: {} }
          }
        }),
        prisma.symbol.count({
          where: {
            scores: { some: {} }
          }
        }),
        prisma.symbol.groupBy({
          by: ['sector'],
          _count: true,
          orderBy: { _count: 'desc' }
        }),
        prisma.symbol.groupBy({
          by: ['market'],
          _count: true,
          orderBy: { _count: 'desc' }
        }),
        prisma.marketData.findFirst({
          orderBy: { date: 'desc' },
          select: { date: true }
        })
      ]);

      return {
        totalSymbols,
        symbolsWithMarketData,
        symbolsWithScores,
        sectors: sectors.map(s => ({ name: s.sector, count: s._count })),
        markets: markets.map(m => ({ name: m.market, count: m._count })),
        latestUpdate: latestMarketData?.date || null
      };
    } catch (error) {
      console.error('خطا در دریافت آمار نمادها:', error);
      throw new Error('خطا در دریافت آمار نمادها');
    }
  }

  /**
   * جستجوی پیشرفته نمادها
   */
  async searchSymbolsAdvanced(query: {
    text?: string;
    sector?: string[];
    market?: string[];
    minPrice?: number;
    maxPrice?: number;
    hasScores?: boolean;
    limit?: number;
    offset?: number;
  }): Promise<SymbolWithMarketData[]> {
    try {
      const where: Prisma.SymbolWhereInput = {};

      // جستجوی متنی
      if (query.text) {
        where.OR = [
          { symbol: { contains: query.text } },
          { name: { contains: query.text } },
          { isin: { contains: query.text } }
        ];
      }

      // فیلتر بخش‌ها
      if (query.sector && query.sector.length > 0) {
        where.sector = { in: query.sector };
      }

      // فیلتر بازارها
      if (query.market && query.market.length > 0) {
        where.market = { in: query.market };
      }

      // فیلتر امتیاز
      if (query.hasScores !== undefined) {
        where.scores = query.hasScores ? { some: {} } : { none: {} };
      }

      // فیلتر قیمت (نیاز به join با marketData دارد)
      if (query.minPrice !== undefined || query.maxPrice !== undefined) {
        where.marketData = {
          some: {
            price: {
              ...(query.minPrice !== undefined && { gte: query.minPrice }),
              ...(query.maxPrice !== undefined && { lte: query.maxPrice })
            }
          }
        };
      }

      const symbols = await prisma.symbol.findMany({
        where,
        include: {
          marketData: {
            orderBy: { date: 'desc' },
            take: 1
          },
          scores: {
            where: {
              validTo: { gte: new Date() }
            },
            orderBy: { calculationDate: 'desc' },
            take: 1
          }
        },
        take: query.limit || 50,
        skip: query.offset || 0,
        orderBy: { symbol: 'asc' }
      });

      return symbols.map(symbol => ({
        ...symbol,
        latestMarketData: symbol.marketData[0] || null,
        score: symbol.scores[0] ? symbol.scores[0].value : undefined
      }));
    } catch (error) {
      console.error('خطا در جستجوی پیشرفته نمادها:', error);
      throw new Error('خطا در جستجوی پیشرفته نمادها');
    }
  }

  /**
   * وارد کردن دسته‌ای نمادها
   */
  async importSymbolsBatch(symbolsData: Array<{
    isin: string;
    symbol: string;
    name: string;
    market: string;
    sector: string;
    subSector?: string;
  }>): Promise<{
    success: number;
    failed: number;
    errors: Array<{ isin: string; error: string }>;
  }> {
    try {
      const results = {
        success: 0,
        failed: 0,
        errors: [] as Array<{ isin: string; error: string }>
      };

      // استفاده از تراکنش برای عملکرد بهتر
      await prisma.$transaction(async (tx) => {
        for (const symbolData of symbolsData) {
          try {
            // بررسی تکراری نبودن
            const existing = await tx.symbol.findFirst({
              where: {
                OR: [
                  { isin: symbolData.isin },
                  { symbol: symbolData.symbol }
                ]
              }
            });

            if (existing) {
              results.failed++;
              results.errors.push({
                isin: symbolData.isin,
                error: `نماد با ISIN ${symbolData.isin} یا کد ${symbolData.symbol} قبلاً وجود دارد`
              });
              continue;
            }

            await tx.symbol.create({
              data: symbolData
            });

            results.success++;
          } catch (error) {
            results.failed++;
            results.errors.push({
              isin: symbolData.isin,
              error: error instanceof Error ? error.message : 'خطای ناشناخته'
            });
          }
        }
      });

      return results;
    } catch (error) {
      console.error('خطا در وارد کردن دسته‌ای نمادها:', error);
      throw new Error('خطا در وارد کردن دسته‌ای نمادها');
    }
  }

  /**
   * به‌روزرسانی دسته‌ای داده‌های بازار
   */
  async updateMarketDataBatch(updates: Array<{
    symbolId: string;
    date: Date;
    data: Partial<MarketData>;
  }>): Promise<{
    success: number;
    failed: number;
    errors: Array<{ symbolId: string; date: Date; error: string }>;
  }> {
    try {
      const results = {
        success: 0,
        failed: 0,
        errors: [] as Array<{ symbolId: string; date: Date; error: string }>
      };

      // استفاده از تراکنش برای عملکرد بهتر
      await prisma.$transaction(async (tx) => {
        for (const update of updates) {
          try {
            // بررسی وجود رکورد
            const existing = await tx.marketData.findUnique({
              where: {
                symbolId_date: {
                  symbolId: update.symbolId,
                  date: update.date
                }
              }
            });

            if (!existing) {
              results.failed++;
              results.errors.push({
                symbolId: update.symbolId,
                date: update.date,
                error: 'رکورد مورد نظر یافت نشد'
              });
              continue;
            }

            await tx.marketData.update({
              where: {
                symbolId_date: {
                  symbolId: update.symbolId,
                  date: update.date
                }
              },
              data: update.data
            });

            results.success++;
          } catch (error) {
            results.failed++;
            results.errors.push({
              symbolId: update.symbolId,
              date: update.date,
              error: error instanceof Error ? error.message : 'خطای ناشناخته'
            });
          }
        }
      });

      return results;
    } catch (error) {
      console.error('خطا در به‌روزرسانی دسته‌ای داده‌های بازار:', error);
      throw new Error('خطا در به‌روزرسانی دسته‌ای داده‌های بازار');
    }
  }
}

// ایجاد نمونه singleton از سرویس
export const symbolService = new SymbolService();